    expect([at("two-flocks", sheep, 0.5), all("two-flocks", ways, 0.5), at("two-flocks", sheep, 0.66), all("two-flocks", ways, 0.66)]).toEqual([[1, -31.5, 0], [1, 0, 0], [1, 31.5, 0], [1, 1, 0]]);
