    expect([fasted.map((name) => at("gate-ar-rayyan", name, 0.81)), all("gate-ar-rayyan", [...crescents, ...called], 0.81), value("gate-ar-rayyan", door, "scaleX", 0.81)]).toEqual([[[0, 86, -19], [0, 74, -20.4], [0, 62, -19]], [0, 0, 0, 0, 0, 0], 0.14]);
