    expect([at("make-it-easy", edge, 1), coming.map((name) => at("make-it-easy", name, 1)), shown("make-it-easy", "a way off, away", 1), at("make-it-easy", "a warm glow on them, glad", 1)]).toEqual([[1, 44, 5.4], [1, 1, 1].map(() => [1, 58, -0.6]), 0, [1, 20, -0.6]]);
