    expect([value("hour-on-friday", band, "scaleX", 0.78), marks.map((name) => at("hour-on-friday", name, 0.78)), shown("hour-on-friday", "the hour, short, shining", 0.78)]).toEqual([1, [[0, 0, 0], [0, 0, 0]], 0]);
